import re

from supplier_loop.round_state.models import QuoteLine, RfqContext

_TRAILING_PARENS = re.compile(r"\s*\([^)]*\)\s*$")


def description_catalog(rfq: RfqContext) -> dict[str, str]:
    grouped: dict[str, set[str]] = {}
    for material_id, description in _catalog_pairs(rfq):
        key = canonical_description(description)
        grouped.setdefault(key, set()).add(material_id)
    return {key: next(iter(ids)) for key, ids in grouped.items() if len(ids) == 1}


def canonical_description(description: str) -> str:
    stripped = _TRAILING_PARENS.sub("", description)
    return " ".join(stripped.casefold().split())


def normalize_quote_line(line: QuoteLine, catalog: Mapping[str, str]) -> QuoteLine:
    if line.material_id:
        return line.model_copy(deep=True)
    material_id = catalog.get(canonical_description(line.description))
    return line.model_copy(deep=True, update={"material_id": material_id})


def _catalog_pairs(rfq: RfqContext) -> Sequence[tuple[str, str]]:
    pairs: list[tuple[str, str]] = [
        (line.material_id, line.description) for line in rfq.assignment.line_items
    ]
    pairs.extend((row.material_id, row.description) for row in rfq.price_history)
    return pairs

from collections.abc import Sequence


def recomputed_line_total(quantity: float, unit_price: float) -> float:
    return quantity * unit_price


def recomputed_grand_total(line_totals: Sequence[float]) -> float:
    return float(sum(line_totals))

import json
from pathlib import Path

from supplier_loop.simulator.port import EmailMessage

_REPO_ROOT = Path(__file__).resolve().parents[2]
_SAMPLE_EMAILS = _REPO_ROOT / "docs/fixtures/sample_traffic/emails"
_APPROVER_FIXTURE = (
    Path(__file__).resolve().parent / "mail_kind" / "fixtures" / "approver_ruling.json"
)


def email_from_json(path: Path) -> EmailMessage:
    data = json.loads(path.read_text(encoding="utf-8"))
    attachments = data.get("attachments") or []
    return EmailMessage(
        id=data["id"],
        from_address=data["from"],
        to_address=data["to"],
        subject=data["subject"],
        sim_time_hours=float(data["sim_time_hours"]),
        attachment_ids=list(attachments),
        body=data["body"],
    )


def load_sample_email(email_id: str) -> EmailMessage:
    for path in sorted(_SAMPLE_EMAILS.glob("*.json")):
        message = email_from_json(path)
        if message.id == email_id:
            return message
    raise KeyError(email_id)


def load_approver_ruling() -> EmailMessage:
    return email_from_json(_APPROVER_FIXTURE)


def sample_email_paths() -> list[Path]:
    return sorted(_SAMPLE_EMAILS.glob("*.json"))

